const MAX_CLASSROOMS_PER_TEACHER = 50;

async create(teacherId: string, body: CreateClassroomBody): Promise<Classroom> {
  const id = await this.db.transaction().execute(async (trx) => {
    await sql`SELECT 1 FROM users WHERE id = ${teacherId} FOR UPDATE`.execute(trx);
    const { n } = await trx.selectFrom('classrooms').select((eb) => eb.fn.countAll<string>().as('n'))
      .where('teacher_id', '=', teacherId).executeTakeFirstOrThrow();
    if (Number(n) >= MAX_CLASSROOMS_PER_TEACHER)
      throw new AppError('RATE_LIMITED', 'Classroom limit reached.'); // or a dedicated QUOTA_EXCEEDED code
    const { id } = await new ClassroomRepository(trx).insert({ teacherId, name: body.name, description: emptyToNull(body.description) });
    await this.issueCode(trx, id);
    return id;
  });
  return this.get(teacherId, id);
}
